content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Food Truck Owner",
      "description": "Person who operates and manages the food truck daily"
    },
    {
      "name": "Daily Route",
      "description": "Planned path for the food truck to reach customer locations"
    },
    {
      "name": "Food Truck",
      "description": "Vehicle used to prepare and sell meals",
      "attributes": [
        "Daily Route",
        "Menu",
        "Stock Level"
      ]
    },
    {
      "name": "Menu",
      "description": "List of items offered by the food truck",
      "attributes": [
        "Item"
      ]
    },
    {
      "name": "Item",
      "description": "Individual food option on the menu",
      "attributes": [
        "Ingredient"
      ]
    },
    {
      "name": "Ingredient",
      "description": "Component used to prepare items"
    },
    {
      "name": "Stock Level",
      "description": "Current quantity of each ingredient in the food truck",
      "attributes": [
        "Ingredient"
      ]
    },
    {
      "name": "Chef",
      "description": "Person who prepares meals and manages ingredients"
    },
    {
      "name": "Order",
      "description": "Customer request for one or more items",
      "attributes": [
        "Item"
      ]
    },
    {
      "name": "Customer",
      "description": "Person who places an order and pays for items"
    },
    {
      "name": "Payment",
      "description": "Transaction made by customer to purchase food"
    },
    {
      "name": "Supply Vendor",
      "description": "External provider of ingredients to the food truck"
    },
    {
      "name": "Delivery",
      "description": "Transport of ingredients from vendor to truck",
      "attributes": [
        "Ingredient"
      ]
    },
    {
      "name": "Feedback",
      "description": "Customer opinions or suggestions about food or service"
    },
    {
      "name": "Low Stock Report",
      "description": "Notification about running low ingredients sent to vendor"
    }
  ]
}
```
